def call(dep):
    if breaker.state == "open":
        return fallback()
    try:
        r = dep.request()
        breaker.failures = 0
        return r
    except Error:
        breaker.failures = breaker.failures + 1
        if breaker.failures >= 10:
            breaker.state = "open"
        raise
```

